// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IHolderRewards, ITokenRegistry} from "./interfaces/IPontoon.sol";
import {IPonsV2Curve} from "./interfaces/IPonsV2Live.sol";

/// @title BuybackExecutor
/// @notice Holds each token's buyback ETH and lets anyone buy the token on its Pons V2 bonding curve,
///         delivering the tokens straight to 0x...dEaD.
///         After graduation the token trades on Uniswap V4, which this executor does not route yet;
///         pending ETH can then be redirected (by anyone) to the token's stakers, so it never sits idle.
/// @dev Owner (Pontoon multisig) can only pause new buybacks. It cannot move ETH.
contract BuybackExecutor is Ownable, ReentrancyGuard {
    address public constant BURN_ADDRESS = 0x000000000000000000000000000000000000dEaD;
    uint256 public constant MAX_BUYBACK_ETH = 0.5 ether;
    uint256 public constant MAX_LIQUIDITY_BPS = 100; // 1% of the curve's quote reserve

    ITokenRegistry public immutable registry;

    bool public paused;
    mapping(address token => uint256) public pendingETH;
    mapping(address token => uint256) public totalETHSpent;
    mapping(address token => uint256) public totalBurned;
    mapping(address token => uint256) public totalRedirected;

    event BuybackFunded(address indexed token, uint256 amount);
    event BuybackExecuted(address indexed token, uint256 ethIn, uint256 tokensBurned);
    event BuybackRedirectedToRewards(address indexed token, uint256 amount);
    event Paused(bool paused);

    error NotRegistered();
    error IsPaused();
    error ZeroMinOut();
    error ZeroAmount();
    error InsufficientPending();
    error ExceedsCap(uint256 cap);
    error Slippage();
    error Graduated();
    error NotGraduated();

    constructor(address owner_, ITokenRegistry registry_) Ownable(owner_) {
        registry = registry_;
    }

    function setPaused(bool p) external onlyOwner {
        paused = p;
        emit Paused(p);
    }

    /// @notice Called by FeeVault during distribute(). Never paused.
    function depositFor(address token) external payable {
        if (!registry.isRegistered(token)) revert NotRegistered();
        pendingETH[token] += msg.value;
        emit BuybackFunded(token, msg.value);
    }

    function _curve(address token) internal view returns (IPonsV2Curve) {
        return IPonsV2Curve(registry.getToken(token).curve);
    }

    /// @notice Max ETH per execution: min(0.5 ETH, 1% of the curve's quote reserve). Zero after graduation.
    function maxBuyback(address token) public view returns (uint256 cap) {
        IPonsV2Curve curve = _curve(token);
        if (curve.graduated()) return 0;
        cap = curve.quoteReserve() * MAX_LIQUIDITY_BPS / 10_000;
        if (cap > MAX_BUYBACK_ETH) cap = MAX_BUYBACK_ETH;
    }

    /// @notice Permissionless. Buys on the bonding curve with `amount` of the token's pending ETH and
    ///         sends the tokens to 0x...dEaD. `minOut` is mandatory to limit sandwiching.
    function buybackAndBurn(address token, uint256 amount, uint256 minOut)
        external
        nonReentrant
        returns (uint256 burned)
    {
        if (paused) revert IsPaused();
        if (amount == 0) revert ZeroAmount();
        if (minOut == 0) revert ZeroMinOut();
        if (amount > pendingETH[token]) revert InsufficientPending();
        IPonsV2Curve curve = _curve(token);
        if (curve.graduated()) revert Graduated();
        uint256 cap = maxBuyback(token);
        if (amount > cap) revert ExceedsCap(cap);

        pendingETH[token] -= amount;
        uint256 before = IERC20(token).balanceOf(BURN_ADDRESS);
        curve.buy{value: amount}(amount, minOut, BURN_ADDRESS);
        burned = IERC20(token).balanceOf(BURN_ADDRESS) - before;
        if (burned < minOut) revert Slippage();

        totalETHSpent[token] += amount;
        totalBurned[token] += burned;
        emit BuybackExecuted(token, amount, burned);
    }

    /// @notice Permissionless, only after graduation: sends the token's pending buyback ETH to its stakers
    ///         (HolderRewards), since Uniswap V4 buybacks are not supported yet.
    function redirectToRewards(address token) external nonReentrant returns (uint256 amount) {
        if (!registry.isRegistered(token)) revert NotRegistered();
        if (!_curve(token).graduated()) revert NotGraduated();
        amount = pendingETH[token];
        if (amount == 0) revert ZeroAmount();
        pendingETH[token] = 0;
        totalRedirected[token] += amount;
        IHolderRewards(registry.getToken(token).holderRewards).notifyReward{value: amount}();
        emit BuybackRedirectedToRewards(token, amount);
    }
}

src/CTOManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IFeeVault, ITokenRegistry} from "./interfaces/IPontoon.sol";

/// @title CTOManager
/// @notice Community takeover: moves FeeVault admin rights to a new team after the multisig
///         approves and a 3-day timelock (mirroring Pons V2) has passed.
/// @dev Flow: anyone requestCTO -> multisig approveCTO -> after eta anyone executeCTO.
///      The current admin, the requester or the multisig can cancel before execution.
contract CTOManager is Ownable {
    uint256 public constant CTO_TIMELOCK = 3 days;

    struct Request {
        address newAdmin;
        address requester;
        uint64 eta;
        bool approved;
    }

    ITokenRegistry public immutable registry;
    mapping(address token => Request) public requests;

    event CTORequested(address indexed token, address indexed newAdmin, uint256 eta);
    event CTOApproved(address indexed token, address indexed newAdmin);
    event CTOExecuted(address indexed token, address indexed oldAdmin, address indexed newAdmin);
    event CTOCancelled(address indexed token);

    error NotRegistered();
    error ZeroAddress();
    error RequestPending();
    error NoRequest();
    error NotApproved();
    error AlreadyApproved();
    error TimelockActive(uint256 eta);
    error NotAuthorized();
    error SameAdmin();

    constructor(address owner_, ITokenRegistry registry_) Ownable(owner_) {
        registry = registry_;
    }

    function requestCTO(address token, address newAdmin) external returns (uint256 eta) {
        if (newAdmin == address(0)) revert ZeroAddress();
        address vault = _vault(token);
        if (IFeeVault(vault).admin() == newAdmin) revert SameAdmin();
        if (requests[token].newAdmin != address(0)) revert RequestPending();
        eta = block.timestamp + CTO_TIMELOCK;
        requests[token] = Request({newAdmin: newAdmin, requester: msg.sender, eta: uint64(eta), approved: false});
        emit CTORequested(token, newAdmin, eta);
    }

    function approveCTO(address token) external onlyOwner {
        Request storage r = requests[token];
        if (r.newAdmin == address(0)) revert NoRequest();
        if (r.approved) revert AlreadyApproved();
        r.approved = true;
        emit CTOApproved(token, r.newAdmin);
    }

    function executeCTO(address token) external {
        Request memory r = requests[token];
        if (r.newAdmin == address(0)) revert NoRequest();
        if (!r.approved) revert NotApproved();
        if (block.timestamp < r.eta) revert TimelockActive(r.eta);
        delete requests[token];
        IFeeVault vault = IFeeVault(_vault(token));
        address oldAdmin = vault.admin();
        vault.setAdmin(r.newAdmin);
        emit CTOExecuted(token, oldAdmin, r.newAdmin);
    }

    function cancelCTO(address token) external {
        Request memory r = requests[token];
        if (r.newAdmin == address(0)) revert NoRequest();
        if (msg.sender != owner() && msg.sender != r.requester && msg.sender != IFeeVault(_vault(token)).admin()) {
            revert NotAuthorized();
        }
        delete requests[token];
        emit CTOCancelled(token);
    }

    function _vault(address token) private view returns (address vault) {
        vault = registry.getToken(token).vault;
        if (vault == address(0)) revert NotRegistered();
    }
}

src/FeeVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {FeeConfig, IPlatformConfig, IHolderRewards, IBuybackExecutor, VaultWiring} from "./interfaces/IPontoon.sol";
import {IPonsV2FeeEscrow, PonsV2Raw} from "./interfaces/IPonsV2Live.sol";

/// @title FeeVault
/// @notice One per token (EIP-1167 clone) and the token's Pons V2 creator-fee recipient.
///         distribute() first pulls the fees in (sweeps the curve through the Pons fee harvester and
///         claims from the Pons FeeEscrow), then splits them:
///         caller incentive -> platform fee -> buyback / holder rewards / creator payout.
/// @dev No admin can withdraw buyback or reward funds. Creator payouts are pull-based.
contract FeeVault is ReentrancyGuard {
    // ---- Parameters (spec "Usulan parameter") ----
    uint256 public constant BPS = 10_000;
    uint16 public constant MAX_BUYBACK_BPS = 8_000;
    uint16 public constant MAX_REWARD_BPS = 5_000;
    uint256 public constant CALLER_INCENTIVE_BPS = 50; // 0.5%
    uint256 public constant MAX_CALLER_INCENTIVE = 0.005 ether;
    uint256 public constant CONFIG_TIMELOCK = 24 hours;

    // ---- Wiring (set once at initialize) ----
    address public token;
    address public curve;
    address public admin;
    address public platformConfig; // PontoonLauncher, source of platformFeeBps
    address public holderRewards;
    address public buybackExecutor;
    address public treasury;
    address public ctoManager;
    address public ponsFeeEscrow;
    address public ponsMemeHook;
    bool private _initialized;

    // ---- Config ----
    FeeConfig public config;
    FeeConfig public pendingConfig;
    uint256 public pendingConfigEta; // 0 = nothing queued

    // ---- Creator payouts (pull) ----
    mapping(address => uint256) public creatorOwed;
    uint256 public totalCreatorOwed;

    // ---- Stats ----
    uint256 public totalReceived;
    uint256 public totalDistributed;

    event FeeReceived(address indexed token, uint256 amount);
    event FeeDistributed(
        address indexed token, uint256 platform, uint256 creator, uint256 buyback, uint256 rewards, address caller
    );
    event CallerIncentivePaid(address indexed token, address indexed caller, uint256 amount);
    event ConfigQueued(address indexed token, FeeConfig newConfig, uint256 eta);
    event ConfigApplied(address indexed token, FeeConfig newConfig);
    event ConfigCancelled(address indexed token);
    event CreatorClaimed(address indexed token, address indexed account, uint256 amount);
    event AdminChanged(address indexed token, address indexed oldAdmin, address indexed newAdmin);
    event FeesCollected(address indexed token, bool harvested, uint256 claimed);

    error AlreadyInitialized();
    error NotAdmin();
    error NotCTOManager();
    error InvalidConfig();
    error NothingToDistribute();
    error NothingQueued();
    error TimelockActive(uint256 eta);
    error NothingToClaim();
    error TransferFailed();
    error ZeroAddress();

    modifier onlyAdmin() {
        if (msg.sender != admin) revert NotAdmin();
        _;
    }

    constructor() {
        // Lock the implementation; only clones get initialized.
        _initialized = true;
    }

    function initialize(VaultWiring calldata w, FeeConfig calldata config_) external {
        if (_initialized) revert AlreadyInitialized();
        if (
            w.token == address(0) || w.curve == address(0) || w.admin == address(0) || w.holderRewards == address(0)
                || w.buybackExecutor == address(0) || w.treasury == address(0) || w.ctoManager == address(0)
                || w.ponsFeeEscrow == address(0) || w.ponsMemeHook == address(0)
        ) revert ZeroAddress();
        validateConfig(config_);
        _initialized = true;
        token = w.token;
        curve = w.curve;
        admin = w.admin;
        platformConfig = msg.sender;
        holderRewards = w.holderRewards;
        buybackExecutor = w.buybackExecutor;
        treasury = w.treasury;
        ctoManager = w.ctoManager;
        ponsFeeEscrow = w.ponsFeeEscrow;
        ponsMemeHook = w.ponsMemeHook;
        config = config_;
        emit ConfigApplied(w.token, config_);
    }

    receive() external payable {
        totalReceived += msg.value;
        emit FeeReceived(token, msg.value);
    }

    // ------------------------------------------------------------------
    // Distribution
    // ------------------------------------------------------------------

    /// @notice ETH currently waiting to be distributed (excludes unclaimed creator payouts).
    ///         Does not include fees still held by Pons; see claimableFromPons().
    function pendingDistribution() public view returns (uint256) {
        return address(this).balance - totalCreatorOwed;
    }

    /// @notice Creator fees Pons has already credited to this vault in its FeeEscrow.
    ///         Fees still inside the curve (not yet swept) are not included.
    function claimableFromPons() public view returns (uint256) {
        return IPonsV2FeeEscrow(ponsFeeEscrow).balanceOf(address(this));
    }

    /// @notice Permissionless. Pulls this token's creator fees from Pons into the vault:
    ///         sweeps the curve via the Pons fee harvester, then claims from the FeeEscrow.
    ///         Never reverts, so a Pons-side hiccup cannot block distributing what is already here.
    function collectFees() public returns (uint256 claimed) {
        bool harvested = PonsV2Raw.harvest(PonsV2Raw.feeHarvester(ponsMemeHook), curve);
        IPonsV2FeeEscrow escrow = IPonsV2FeeEscrow(ponsFeeEscrow);
        try escrow.balanceOf(address(this)) returns (uint256 credited) {
            if (credited > 0) {
                try escrow.claim() returns (uint256 amount) {
                    claimed = amount;
                } catch {}
            }
        } catch {}
        emit FeesCollected(token, harvested, claimed);
    }

    /// @notice Preview how `amount` would be split under the active config.
    function previewSplit(uint256 amount)
        public
        view
        returns (uint256 incentive, uint256 platform, uint256 creator, uint256 buyback, uint256 rewards)
    {
        incentive = amount * CALLER_INCENTIVE_BPS / BPS;
        if (incentive > MAX_CALLER_INCENTIVE) incentive = MAX_CALLER_INCENTIVE;
        uint256 rest = amount - incentive;
        platform = rest * IPlatformConfig(platformConfig).platformFeeBps() / BPS;
        uint256 remainder = rest - platform;
        FeeConfig memory c = config;
        buyback = remainder * c.buybackBps / BPS;
        rewards = remainder * c.rewardBps / BPS;
        creator = remainder - buyback - rewards;
    }

    /// @notice Permissionless. Pulls fees from Pons, splits all pending ETH and pays the caller a small incentive.
    function distribute() external nonReentrant {
        collectFees();
        uint256 amount = pendingDistribution();
        if (amount == 0) revert NothingToDistribute();

        (uint256 incentive, uint256 platform, uint256 creator, uint256 buyback, uint256 rewards) = previewSplit(amount);

        totalDistributed += amount;
        if (creator > 0) {
            creatorOwed[admin] += creator;
            totalCreatorOwed += creator;
        }

        if (platform > 0) _send(treasury, platform);
        if (buyback > 0) IBuybackExecutor(buybackExecutor).depositFor{value: buyback}(token);
        if (rewards > 0) IHolderRewards(holderRewards).notifyReward{value: rewards}();
        if (incentive > 0) {
            _send(msg.sender, incentive);
            emit CallerIncentivePaid(token, msg.sender, incentive);
        }

        emit FeeDistributed(token, platform, creator, buyback, rewards, msg.sender);
    }

    /// @notice Pull the creator payout owed to msg.sender. Works for past admins too,
    ///         so a CTO never confiscates payouts that were already earned.
    function claimCreator() external nonReentrant returns (uint256 amount) {
        amount = creatorOwed[msg.sender];
        if (amount == 0) revert NothingToClaim();
        creatorOwed[msg.sender] = 0;
        totalCreatorOwed -= amount;
        _send(msg.sender, amount);
        emit CreatorClaimed(token, msg.sender, amount);
    }

    // ------------------------------------------------------------------
    // Config (24h timelock)
    // ------------------------------------------------------------------

    function validateConfig(FeeConfig memory c) public pure {
        if (c.buybackBps > MAX_BUYBACK_BPS || c.rewardBps > MAX_REWARD_BPS) revert InvalidConfig();
        if (uint256(c.buybackBps) + c.rewardBps > BPS) revert InvalidConfig();
    }

    function queueConfig(FeeConfig calldata newConfig) external onlyAdmin {
        validateConfig(newConfig);
        uint256 eta = block.timestamp + CONFIG_TIMELOCK;
        pendingConfig = newConfig;
        pendingConfigEta = eta;
        emit ConfigQueued(token, newConfig, eta);
    }

    /// @notice Permissionless once the timelock has passed.
    function applyConfig() external {
        uint256 eta = pendingConfigEta;
        if (eta == 0) revert NothingQueued();
        if (block.timestamp < eta) revert TimelockActive(eta);
        FeeConfig memory c = pendingConfig;
        config = c;
        delete pendingConfig;
        pendingConfigEta = 0;
        emit ConfigApplied(token, c);
    }

    function cancelConfig() external onlyAdmin {
        if (pendingConfigEta == 0) revert NothingQueued();
        delete pendingConfig;
        pendingConfigEta = 0;
        emit ConfigCancelled(token);
    }

    // ------------------------------------------------------------------
    // CTO
    // ------------------------------------------------------------------

    /// @notice Only CTOManager, after its own 3-day timelock. Drops any config queued by the old admin.
    function setAdmin(address newAdmin) external {
        if (msg.sender != ctoManager) revert NotCTOManager();
        if (newAdmin == address(0)) revert ZeroAddress();
        address old = admin;
        admin = newAdmin;
        if (pendingConfigEta != 0) {
            delete pendingConfig;
            pendingConfigEta = 0;
            emit ConfigCancelled(token);
        }
        emit AdminChanged(token, old, newAdmin);
    }

    function _send(address to, uint256 amount) private {
        (bool ok,) = to.call{value: amount}("");
        if (!ok) revert TransferFailed();
    }
}

src/HolderRewards.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title HolderRewards
/// @notice One per token (EIP-1167 clone). Holders stake the token and earn ETH using a
///         reward-per-share accumulator. Only stakers earn, so LP pools and the burn address
///         are excluded automatically.
/// @dev No admin and no withdraw function: ETH can only leave via claim().
contract HolderRewards is ReentrancyGuard {
    using SafeERC20 for IERC20;

    uint256 private constant PRECISION = 1e24;

    IERC20 public stakingToken;
    bool private _initialized;

    uint256 public totalStaked;
    uint256 public accRewardPerShare;
    /// @notice ETH received while nobody was staked; released on the next notify with stakers.
    uint256 public queuedRewards;
    uint256 public totalRewardsNotified;

    mapping(address => uint256) public stakedOf;
    mapping(address => uint256) public rewardDebt;
    mapping(address => uint256) public owed;

    event Staked(address indexed token, address indexed user, uint256 amount);
    event Unstaked(address indexed token, address indexed user, uint256 amount);
    event RewardClaimed(address indexed token, address indexed user, uint256 amount);
    event RewardNotified(address indexed token, uint256 amount, uint256 released);

    error AlreadyInitialized();
    error ZeroAmount();
    error InsufficientStake();
    error NothingToClaim();
    error TransferFailed();

    constructor() {
        _initialized = true;
    }

    function initialize(address token_) external {
        if (_initialized) revert AlreadyInitialized();
        _initialized = true;
        stakingToken = IERC20(token_);
    }

    /// @notice Anyone may add ETH rewards (FeeVault does so on distribute()).
    function notifyReward() external payable {
        totalRewardsNotified += msg.value;
        uint256 amount = queuedRewards + msg.value;
        if (totalStaked == 0) {
            queuedRewards = amount;
            emit RewardNotified(address(stakingToken), msg.value, 0);
            return;
        }
        queuedRewards = 0;
        accRewardPerShare += amount * PRECISION / totalStaked;
        emit RewardNotified(address(stakingToken), msg.value, amount);
    }

    function pendingReward(address user) public view returns (uint256) {
        return owed[user] + stakedOf[user] * accRewardPerShare / PRECISION - rewardDebt[user];
    }

    function stake(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        _settle(msg.sender);
        uint256 before = stakingToken.balanceOf(address(this));
        stakingToken.safeTransferFrom(msg.sender, address(this), amount);
        uint256 received = stakingToken.balanceOf(address(this)) - before;
        stakedOf[msg.sender] += received;
        totalStaked += received;
        rewardDebt[msg.sender] = stakedOf[msg.sender] * accRewardPerShare / PRECISION;
        emit Staked(address(stakingToken), msg.sender, received);
    }

    function unstake(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        if (stakedOf[msg.sender] < amount) revert InsufficientStake();
        _settle(msg.sender);
        stakedOf[msg.sender] -= amount;
        totalStaked -= amount;
        rewardDebt[msg.sender] = stakedOf[msg.sender] * accRewardPerShare / PRECISION;
        stakingToken.safeTransfer(msg.sender, amount);
        emit Unstaked(address(stakingToken), msg.sender, amount);
    }

    function claim() external nonReentrant returns (uint256 amount) {
        _settle(msg.sender);
        amount = owed[msg.sender];
        if (amount == 0) revert NothingToClaim();
        owed[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: amount}("");
        if (!ok) revert TransferFailed();
        emit RewardClaimed(address(stakingToken), msg.sender, amount);
    }

    function _settle(address user) private {
        uint256 accumulated = stakedOf[user] * accRewardPerShare / PRECISION;
        owed[user] += accumulated - rewardDebt[user];
        rewardDebt[user] = accumulated;
    }
}

src/PlatformTreasury.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title PlatformTreasury
/// @notice Collects the platform fee. Withdrawals require the multisig owner and a timelock.
contract PlatformTreasury is Ownable, ReentrancyGuard {
    uint256 public constant WITHDRAW_DELAY = 48 hours;

    struct Withdrawal {
        address to;
        uint256 amount;
        uint64 eta;
        bool executed;
        bool cancelled;
    }

    Withdrawal[] public withdrawals;
    uint256 public totalReceived;

    event PlatformFeeReceived(address indexed from, uint256 amount);
    event WithdrawQueued(uint256 indexed id, address indexed to, uint256 amount, uint256 eta);
    event WithdrawExecuted(uint256 indexed id, address indexed to, uint256 amount);
    event WithdrawCancelled(uint256 indexed id);

    error ZeroAddress();
    error UnknownWithdrawal();
    error NotQueued();
    error TimelockActive(uint256 eta);
    error TransferFailed();

    constructor(address owner_) Ownable(owner_) {}

    receive() external payable {
        totalReceived += msg.value;
        emit PlatformFeeReceived(msg.sender, msg.value);
    }

    function queueWithdraw(address to, uint256 amount) external onlyOwner returns (uint256 id) {
        if (to == address(0)) revert ZeroAddress();
        id = withdrawals.length;
        uint64 eta = uint64(block.timestamp + WITHDRAW_DELAY);
        withdrawals.push(Withdrawal({to: to, amount: amount, eta: eta, executed: false, cancelled: false}));
        emit WithdrawQueued(id, to, amount, eta);
    }

    function withdraw(uint256 id) external onlyOwner nonReentrant {
        Withdrawal storage w = _get(id);
        if (block.timestamp < w.eta) revert TimelockActive(w.eta);
        w.executed = true;
        (bool ok,) = w.to.call{value: w.amount}("");
        if (!ok) revert TransferFailed();
        emit WithdrawExecuted(id, w.to, w.amount);
    }

    function cancelWithdraw(uint256 id) external onlyOwner {
        _get(id).cancelled = true;
        emit WithdrawCancelled(id);
    }

    function withdrawalCount() external view returns (uint256) {
        return withdrawals.length;
    }

    function _get(uint256 id) private view returns (Withdrawal storage w) {
        if (id >= withdrawals.length) revert UnknownWithdrawal();
        w = withdrawals[id];
        if (w.executed || w.cancelled) revert NotQueued();
    }
}

src/PontoonLauncher.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {
    FeeConfig,
    IFeeVault,
    IHolderRewards,
    IPlatformConfig,
    ITokenRegistry,
    VaultWiring
} from "./interfaces/IPontoon.sol";
import {IPonsV2Curve, IPonsV2LaunchFactory} from "./interfaces/IPonsV2Live.sol";

/// @title PontoonLauncher
/// @notice Entry point for launches. Clones a FeeVault + HolderRewards per token, launches the token on the
///         live Pons V2 factory with the FeeVault as creator-fee recipient, registers it, and (optionally)
///         buys for the creator in the same transaction, exempt from the launch snipe tax.
///         Also holds the global platform fee that every FeeVault reads.
contract PontoonLauncher is IPlatformConfig, Ownable, ReentrancyGuard {
    uint16 public constant MAX_PLATFORM_FEE_BPS = 3_000;
    uint16 public constant DEFAULT_BUYBACK_BPS = 4_000;
    uint16 public constant DEFAULT_REWARD_BPS = 2_000;
    address public constant ETH = address(0);

    struct TokenMeta {
        string name;
        string symbol;
        string logo; // image URL
        string description;
        string twitter;
        string telegram;
        string website;
    }

    IPonsV2LaunchFactory public immutable ponsFactory;
    ITokenRegistry public immutable registry;
    address public immutable feeVaultImpl;
    address public immutable holderRewardsImpl;
    address public immutable buybackExecutor;
    address public immutable treasury;
    address public immutable ctoManager;

    uint16 public platformFeeBps = 2_000;
    /// @notice Creators pick their token's Pons creator tax (paid on curve trades into the FeeVault) between
    ///         `minCreatorTaxBps` and the Pons maximum. `defaultCreatorTaxBps` is used by launchWithDefaultConfig.
    uint16 public minCreatorTaxBps = 100;
    uint16 public defaultCreatorTaxBps = 100;
    uint256 public launchConfigId; // Pons launch config (0 = standard 1B supply, 4.2 ETH graduation)
    bool public paused;
    /// @notice Allowed quote pairs. Only ETH (address(0)) is supported for now.
    mapping(address => bool) public quotePairAllowed;
    uint256 public launchCount;

    event TokenLaunched(
        address indexed token, address indexed creator, address quotePair, bool isMemestock, address vault
    );
    event TokenMetadata(address indexed token, TokenMeta meta);
    event InitialBuy(address indexed token, address indexed creator, uint256 ethIn, uint256 tokensOut);
    event PlatformFeeSet(uint16 bps);
    event CreatorTaxBoundsSet(uint16 minBps, uint16 defaultBps);
    event LaunchConfigIdSet(uint256 id);
    event QuotePairSet(address indexed quoteAsset, bool allowed);
    event Paused(bool paused);

    error IsPaused();
    error QuotePairNotAllowed();
    error FeeTooHigh();
    error CreatorTaxOutOfRange(uint16 minBps, uint16 maxBps);
    error InsufficientLaunchFee(uint256 required);
    error PonsLaunchDisabled();

    constructor(
        address owner_,
        IPonsV2LaunchFactory ponsFactory_,
        ITokenRegistry registry_,
        address feeVaultImpl_,
        address holderRewardsImpl_,
        address buybackExecutor_,
        address treasury_,
        address ctoManager_
    ) Ownable(owner_) {
        ponsFactory = ponsFactory_;
        registry = registry_;
        feeVaultImpl = feeVaultImpl_;
        holderRewardsImpl = holderRewardsImpl_;
        buybackExecutor = buybackExecutor_;
        treasury = treasury_;
        ctoManager = ctoManager_;
        quotePairAllowed[ETH] = true;
        emit QuotePairSet(ETH, true);
    }

    // ---- Admin (multisig) ----

    function setPlatformFeeBps(uint16 bps) external onlyOwner {
        if (bps > MAX_PLATFORM_FEE_BPS) revert FeeTooHigh();
        platformFeeBps = bps;
        emit PlatformFeeSet(bps);
    }

    /// @notice Lowest creator tax creators may pick, and the default, for future launches.
    function setCreatorTaxBounds(uint16 minBps, uint16 defaultBps) external onlyOwner {
        uint16 maxBps = maxCreatorTaxBps();
        if (minBps > defaultBps || defaultBps > maxBps) revert CreatorTaxOutOfRange(minBps, maxBps);
        minCreatorTaxBps = minBps;
        defaultCreatorTaxBps = defaultBps;
        emit CreatorTaxBoundsSet(minBps, defaultBps);
    }

    function setLaunchConfigId(uint256 id) external onlyOwner {
        launchConfigId = id;
        emit LaunchConfigIdSet(id);
    }

    /// @notice Non-ETH pairs (USDG, tokenized stocks) need ERC-20 quote handling that is not wired yet,
    ///         so only ETH can be enabled for now.
    function setQuotePair(address quoteAsset, bool allowed) external onlyOwner {
        if (allowed && quoteAsset != ETH) revert QuotePairNotAllowed();
        quotePairAllowed[quoteAsset] = allowed;
        emit QuotePairSet(quoteAsset, allowed);
    }

    function setPaused(bool p) external onlyOwner {
        paused = p;
        emit Paused(p);
    }

    // ---- Launch ----

    function defaultFeeConfig() public pure returns (FeeConfig memory) {
        return FeeConfig({buybackBps: DEFAULT_BUYBACK_BPS, rewardBps: DEFAULT_REWARD_BPS});
    }

    /// @notice Highest creator tax a creator may pick: the Pons V2 factory's maximum (10% on mainnet).
    function maxCreatorTaxBps() public view returns (uint16) {
        uint256 max = ponsFactory.maxCreatorTaxBps();
        return max > type(uint16).max ? type(uint16).max : uint16(max);
    }

    /// @notice ETH required on top of any initial buy.
    function launchFee() public view returns (uint256) {
        return ponsFactory.launchFee();
    }

    /// @notice Launch with a custom fee split and creator tax (in bps, between `minCreatorTaxBps` and
    ///         `maxCreatorTaxBps()`). `msg.value` = Pons launch fee + optional initial buy for the creator.
    function launch(
        TokenMeta calldata meta,
        address quotePair,
        bool isMemestock,
        FeeConfig calldata feeConfig,
        uint16 creatorTaxBps
    ) external payable nonReentrant returns (address token, address vault) {
        return _launch(meta, quotePair, isMemestock, feeConfig, creatorTaxBps);
    }

    /// @notice Launch with the default split (40% buyback, 20% rewards, 40% creator) and default creator tax.
    function launchWithDefaultConfig(TokenMeta calldata meta, address quotePair, bool isMemestock)
        external
        payable
        nonReentrant
        returns (address token, address vault)
    {
        return _launch(meta, quotePair, isMemestock, defaultFeeConfig(), defaultCreatorTaxBps);
    }

    function _launch(
        TokenMeta calldata meta,
        address quotePair,
        bool isMemestock,
        FeeConfig memory feeConfig,
        uint16 creatorTaxBps
    ) private returns (address token, address vault) {
        if (paused) revert IsPaused();
        uint16 maxBps = maxCreatorTaxBps();
        if (creatorTaxBps < minCreatorTaxBps || creatorTaxBps > maxBps) {
            revert CreatorTaxOutOfRange(minCreatorTaxBps, maxBps);
        }
        if (!quotePairAllowed[quotePair] || quotePair != ETH) revert QuotePairNotAllowed();
        if (!ponsFactory.launchEnabled()) revert PonsLaunchDisabled();
        uint256 fee = ponsFactory.launchFee();
        if (msg.value < fee) revert InsufficientLaunchFee(fee);

        vault = Clones.clone(feeVaultImpl);
        address rewards = Clones.clone(holderRewardsImpl);

        address curve;
        (token, curve) = _ponsLaunch(meta, vault, creatorTaxBps);

        IHolderRewards(rewards).initialize(token);
        // Reverts on an out-of-bounds feeConfig.
        IFeeVault(vault)
            .initialize(
                VaultWiring({
                    token: token,
                    curve: curve,
                    admin: msg.sender,
                    holderRewards: rewards,
                    buybackExecutor: buybackExecutor,
                    treasury: treasury,
                    ctoManager: ctoManager,
                    ponsFeeEscrow: ponsFactory.feeEscrow(),
                    ponsMemeHook: ponsFactory.memeHook()
                }),
                feeConfig
            );
        registry.register(token, curve, msg.sender, quotePair, isMemestock, vault, rewards);

        emit TokenMetadata(token, meta);
        emit TokenLaunched(token, msg.sender, quotePair, isMemestock, vault);

        uint256 buyAmount = msg.value - fee;
        if (buyAmount > 0) {
            // Same transaction as the launch, so the price cannot move in between.
            uint256 out = IPonsV2Curve(curve).buy{value: buyAmount}(buyAmount, 1, msg.sender);
            emit InitialBuy(token, msg.sender, buyAmount, out);
        }
    }

    function _ponsLaunch(TokenMeta calldata meta, address vault, uint16 creatorTaxBps)
        private
        returns (address token, address curve)
    {
        IPonsV2LaunchFactory.TokenParams memory p;
        p.name = meta.name;
        p.symbol = meta.symbol;
        p.logo = meta.logo;
        p.description = meta.description;
        p.socials.twitter = meta.twitter;
        p.socials.telegram = meta.telegram;
        p.socials.website = meta.website;
        p.creatorFeeRecipient = vault;
        p.creatorTaxBps = creatorTaxBps;
        p.buybackEnabled = false; // Pontoon runs its own buyback-and-burn
        p.expectedEconomics = ponsFactory.previewLaunchEconomics(launchConfigId, ETH);
        p.salt = keccak256(abi.encode(address(this), msg.sender, ++launchCount));

        // The creator's initial buy (recipient = creator) is exempt from the launch snipe tax.
        address[] memory exempt = new address[](1);
        exempt[0] = msg.sender;
        (token, curve) = ponsFactory.launchToken{value: ponsFactory.launchFee()}(p, launchConfigId, ETH, exempt);
    }
}

